// Oeste Carousel — Huntington theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with arbitrary values, JSX transform.
// Requires Huntington tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/huntington/src/index.js
// Docs: https://oeste.hiddeninwest.com/huntington/#/components/carousel

export function Carousel({ images = [] }) {
  return (
    <div className="flex snap-x gap-[10px] overflow-x-auto pb-1">
      {images.map((src, i) => (
        <img key={i} src={src} alt="" className="h-[320px] w-[148px] shrink-0 snap-start rounded-[14px] border border-[var(--color-border)] object-cover" />
      ))}
    </div>
  );
}
